contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, uint256 reqID) public payable {
        require(amount > 0);
        require(interest > 0);
        require(loanToCollateral > 0);
        require(duration > 0);
        require(reqID == 0);

        c.requestLoan(amount, interest, loanToCollateral, duration); if (__ESBMC_reverted()) return;

        bool reverted;
        bool result;
        bool r = c.isActive(reqID); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            result = r;
            reverted = false;
        }

        assert(!reverted && result == true);
    }

    receive() external payable {}
}

