pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, uint256 reqID) internal {
        vm.assume(amount > 0);
        vm.assume(interest > 0);
        vm.assume(loanToCollateral > 0);
        vm.assume(duration > 0);
        reqID = 0;
        try c.requestLoan(amount, interest, loanToCollateral, duration) {} catch { return; }
        bool reverted;
        bool result;
        try c.isActive(reqID) returns (bool r) {
            result = r;
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && result == true);
    }

    function testFuzz_run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, uint256 reqID) public {
        _run(amount, interest, loanToCollateral, duration, reqID);
    }

    receive() external payable {}
}
